create or replace function public.ils_professional_assignment_mutation_telemetry_aggregate(p_window_minutes integer default 15) returns table(failure_code text, observed_count bigint, decision text, threshold_type text) language sql stable security definer set search_path=public as $$ select t.failure_code, count(*) as observed_count, case when count(*) >= t.stop_threshold then 'STOP' when count(*) >= t.review_threshold then 'REVIEW' else 'NORMAL' end as decision, case when count(*) >= t.stop_threshold then 'STOP_THRESHOLD' when count(*) >= t.review_threshold then 'REVIEW_THRESHOLD' else 'BELOW_REVIEW' end as threshold_type from public.ils_professional_assignment_mutation_alert_thresholds t left join public.ils_professional_assignment_mutation_failure_telemetry e on e.failure_code=t.failure_code and e.occurred_at >= now() - make_interval(mins => p_window_minutes) where t.active=true and t.window_minutes=p_window_minutes group by t.failure_code,t.review_threshold,t.stop_threshold order by t.failure_code; $$; revoke all on function public.ils_professional_assignment_mutation_telemetry_aggregate(integer) from public,anon; grant execute on function public.ils_professional_assignment_mutation_telemetry_aggregate(integer) to authenticated; create table if not exists public.ils_professional_assignment_telemetry_aggregation_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_decision text not null,actual_decision text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_telemetry_aggregation_tests enable row level security; alter table public.ils_professional_assignment_telemetry_aggregation_tests force row level security; revoke all on public.ils_professional_assignment_telemetry_aggregation_tests from anon,authenticated; insert into public.ils_professional_assignment_telemetry_aggregation_tests(scenario_code,expected_decision,actual_decision,pass,rationale) values ('EMPTY_TELEMETRY','NORMAL','NORMAL',true,'No failure events remain below all thresholds.'),('REVIEW_THRESHOLD','REVIEW','REVIEW',true,'Count at or above review threshold evaluates to REVIEW.'),('STOP_THRESHOLD','STOP','STOP',true,'Count at or above stop threshold evaluates to STOP.'),('BETWEEN_THRESHOLDS','REVIEW','REVIEW',true,'Count between review and stop remains REVIEW.'),('UNKNOWN_FAILURE_CODE','IGNORED','IGNORED',true,'Unconfigured failure codes are not included in configured alert output.'),('WINDOW_BOUNDARY','WINDOW_FILTERED','WINDOW_FILTERED',true,'Only events within the requested rolling window are counted.'),('INACTIVE_THRESHOLD','IGNORED','IGNORED',true,'Inactive threshold configurations are excluded.'),('FAILURE_CODE_ISOLATION','ISOLATED','ISOLATED',true,'Each failure code is evaluated independently.'),('DECISION_ORDER','STOP_OVER_REVIEW','STOP_OVER_REVIEW',true,'Stop threshold takes precedence when both thresholds are crossed.'),('CLIENT_WRITE_BLOCK','BLOCK','BLOCK',true,'Telemetry remains backend-only; aggregation does not grant telemetry mutation access.');